const std = @import("std");
const builtin = @import("builtin");
const core = @import("../core.zig");
const Reader = @import("fast_bit_reader.zig").Reader;

/// View for at most eight zero-insert commands with no block switch.
/// Each root consumes <=10 Huffman bits and <=24 copy-length bits; its distance
/// consumes <=15 Huffman bits and <=24 extra bits: at most 73 per command.
/// Starting with 96 complete unstaged bytes covers eight such budgets and every
/// 8-byte refill lookahead. The caller must discard the view after the run.
pub const CommandReader = struct {
    base: *Reader,
    budget_end: if (check_budget) usize else void,

    const check_budget = builtin.mode == .Debug or builtin.mode == .ReleaseSafe;
    pub const max_commands = 8;
    pub const input_bytes = 96;
    pub const max_consumed_bits = 73 * max_commands;

    pub inline fn canEnter(reader: *const Reader) bool {
        return reader.bit_len -| (reader.next_byte * 8) >= input_bytes * 8;
    }

    pub inline fn initAssumeAvailable(reader: *Reader) CommandReader {
        std.debug.assert(canEnter(reader));
        return .{ .base = reader, .budget_end = if (check_budget) reader.bitPosition() + max_consumed_bits else {} };
    }

    pub inline fn peekBits9Padded(self: *CommandReader) u9 {
        self.fill(9);
        return @truncate(self.base.bit_buffer);
    }

    pub inline fn peekBits10Padded(self: *CommandReader) u10 {
        self.fill(10);
        return @truncate(self.base.bit_buffer);
    }

    pub inline fn peekBitsPadded(self: *CommandReader, comptime T: type, count: u6) T {
        std.debug.assert(count <= @bitSizeOf(T));
        self.fill(count);
        return @intCast(self.base.bit_buffer & ((@as(u64, 1) << count) - 1));
    }

    pub inline fn hasStagedBits(self: CommandReader, count: u6) bool {
        std.debug.assert(self.base.hasStagedBits(count));
        return true;
    }

    pub inline fn advanceBitsStagedAssumeAvailable(self: *CommandReader, count: u6) void {
        self.base.advanceBitsStagedAssumeAvailable(count);
        if (check_budget) std.debug.assert(self.base.bitPosition() <= self.budget_end);
    }

    pub inline fn readBits(self: *CommandReader, comptime T: type, count: u6) core.Error!T {
        if (count > @bitSizeOf(T)) return error.CorruptFrame;
        const value = self.peekBitsPadded(T, count);
        self.advanceBitsStagedAssumeAvailable(count);
        return value;
    }

    pub inline fn readBits24StagedFirst(self: *CommandReader, count: u5) core.Error!u32 {
        std.debug.assert(count <= 24);
        return self.readBits(u32, count);
    }

    inline fn fill(self: *CommandReader, requested: usize) void {
        std.debug.assert(requested <= 32);
        const reader = self.base;
        if (reader.bit_count >= requested) return;
        if (requested <= 8) {
            std.debug.assert(reader.bit_len -| (reader.next_byte * 8) >= 64);
            const word = std.mem.readInt(u64, reader.input[reader.next_byte..][0..8], .little);
            reader.bit_buffer |= word << @intCast(reader.bit_count);
            reader.bit_count += 56;
            reader.next_byte += 7;
        } else if (requested <= 16) {
            std.debug.assert(reader.bit_len -| (reader.next_byte * 8) >= 64);
            const word = std.mem.readInt(u64, reader.input[reader.next_byte..][0..8], .little);
            reader.bit_buffer |= word << @intCast(reader.bit_count);
            reader.bit_count += 48;
            reader.next_byte += 6;
        } else {
            std.debug.assert(reader.bit_len -| (reader.next_byte * 8) >= 32);
            const word = std.mem.readInt(u32, reader.input[reader.next_byte..][0..4], .little);
            reader.bit_buffer |= @as(u64, word) << @intCast(reader.bit_count);
            reader.bit_count += 32;
            reader.next_byte += 4;
        }
    }
};

test "bounded command reader covers alignment reservoir and maximum bit budget" {
    const bitstream = @import("../bitstream.zig");
    var input: [128]u8 = undefined;
    for (&input, 0..) |*byte, index| byte.* = @truncate(index * 73 + 0xa5);
    var accepted: usize = 0;
    var declined: usize = 0;
    const fields = [_][4]u6{ .{ 10, 24, 15, 24 }, .{ 0, 0, 9, 24 }, .{ 10, 0, 15, 0 }, .{ 0, 0, 0, 0 } };
    for (767..833) |bit_len| {
        for (0..8) |start| {
            for ([_]u6{ 0, 7, 10, 32 }) |warmup| {
                for (0..33) |consumed| {
                    var scalar = bitstream.BitReader.initBitLength(&input, bit_len);
                    try scalar.skipBits(@intCast(start));
                    var prepared = Reader.initFrom(scalar);
                    if (warmup != 0) _ = prepared.peekBitsPadded(u32, warmup);
                    if (!prepared.hasStagedBits(@intCast(consumed))) continue;
                    try scalar.skipBits(@intCast(consumed));
                    prepared.advanceBitsStagedAssumeAvailable(@intCast(consumed));
                    if (!CommandReader.canEnter(&prepared)) {
                        declined += 1;
                        continue;
                    }
                    accepted += 1;
                    for (fields) |widths| {
                        var expected = scalar;
                        var actual = prepared;
                        var bounded = CommandReader.initAssumeAvailable(&actual);
                        for (0..CommandReader.max_commands) |_| {
                            for (widths) |width| {
                                const value = bounded.peekBitsPadded(u32, width);
                                try std.testing.expect(bounded.hasStagedBits(width));
                                bounded.advanceBitsStagedAssumeAvailable(width);
                                try std.testing.expectEqual(try expected.readBits(u32, width), value);
                                try std.testing.expectEqual(expected.bitPosition(), actual.bitPosition());
                            }
                        }
                        // The normal reader resumes exactly after the bounded view.
                        try std.testing.expectEqual(try expected.readBits(u32, 32), try actual.readBits(u32, 32));
                        try std.testing.expectEqual(expected.bitPosition(), actual.bitPosition());
                    }
                }
            }
        }
    }
    try std.testing.expect(accepted != 0 and declined != 0);
}
